//! `sermofur_mcp::mcp_config` against `McpConfigFile` of the oracle
//! (`rust/tests/golden/mcp-config.json`, regenerated by `rust/tools/mcp-config-oracle`): every
//! case, for every entry, byte for byte, refusals and exceptions included. Ports the cases of
//! `McpConfigFileTests` that do not need the CLI (lot 8.1); the install and doctor cases come
//! with lot 8.3.

use std::path::Path;

use serde_json::{Value, json};
use sermofur_core::error::SermofurError;
use sermofur_core::store::sha256_upper;
use sermofur_mcp::mcp_config::{has_entry, with_entry, without_entry};

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02X}")).collect()
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex"))
        .collect()
}

/// The outcome as the oracle writes it.
fn outcome<T>(result: Result<Option<T>, SermofurError>, as_json: impl Fn(T) -> Value) -> Value {
    match result {
        Ok(None) => json!({"null": true}),
        Ok(Some(value)) => as_json(value),
        // The runtime exceptions of the oracle, answered `invalid_storage_or_path` by the CLI.
        Err(error) if error.code == "invalid_storage_or_path" => json!({"exception": "runtime"}),
        Err(error) => {
            json!({"code": error.code, "message": error.message, "exit": error.exit_code})
        }
    }
}

fn bytes(value: Vec<u8>) -> Value {
    if value.len() > 4096 {
        json!({"sha256": sha256_upper(&value), "length": value.len()})
    } else {
        json!({"bytes": hex(&value)})
    }
}

/// The two contents over 4 KiB, which the golden file does not carry.
fn large(name: &str) -> Vec<u8> {
    match name {
        "too_large" => format!("{{\"a\": \"{}\"}}", "x".repeat(1024 * 1024)),
        "exactly_limit" => format!("{{\"a\":\"{}\"}}", "x".repeat(1024 * 1024 - 8)),
        other => panic!("no content for {other}"),
    }
    .into_bytes()
}

#[test]
fn mcp_config_matches_the_oracle() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/mcp-config.json");
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden")).expect("JSON");
    let entries: Vec<(String, Vec<String>)> = golden["entries"]
        .as_array()
        .expect("entries")
        .iter()
        .map(|e| {
            (
                e["command"].as_str().expect("command").to_owned(),
                e["args"]
                    .as_array()
                    .expect("args")
                    .iter()
                    .map(|a| a.as_str().expect("arg").to_owned())
                    .collect(),
            )
        })
        .collect();
    let mut mismatches = Vec::new();
    for ((command, args), expected) in entries
        .iter()
        .zip(golden["absent"].as_array().expect("absent"))
    {
        let got = outcome(with_entry(None, command, args), bytes);
        if &got != expected {
            mismatches.push(format!("absent {command}: {got}"));
        }
    }
    let cases = golden["cases"].as_array().expect("cases");
    for case in cases {
        let name = case["name"].as_str().expect("name");
        let content = case["content"].as_str().map_or_else(|| large(name), unhex);
        for ((command, args), expected) in entries
            .iter()
            .zip(case["withEntry"].as_array().expect("withEntry"))
        {
            let got = outcome(with_entry(Some(&content), command, args), bytes);
            // ArgumentException (duplicate key) and InvalidOperationException (invalid UTF-8).
            let expected = &if expected.get("exception").is_some() {
                json!({"exception": "runtime"})
            } else {
                expected.clone()
            };
            if &got != expected {
                mismatches.push(format!("{name} with {command}: {got}, expected {expected}"));
            }
        }
        let got = outcome(without_entry(&content), bytes);
        if got != case["withoutEntry"] {
            mismatches.push(format!(
                "{name} without: {got}, expected {}",
                case["withoutEntry"]
            ));
        }
        let got = outcome(
            has_entry(&content).map(Some),
            |flag| json!({"object": flag}),
        );
        if got != case["currentEntry"] {
            mismatches.push(format!(
                "{name} current: {got}, expected {}",
                case["currentEntry"]
            ));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
    assert!(cases.len() >= 100, "the golden file lost cases");
}

/// `InstallThenRemoveIsTheIdentity`: whatever the other servers, adding then removing the
/// entry gives back the same bytes.
mod properties {
    use proptest::prelude::*;
    use sermofur_mcp::mcp_config::{with_entry, without_entry};

    proptest! {
        /// Arbitrary bytes, raw or around a valid document: an answer or a refusal, never a
        /// panic; and an added entry reads back as declared and as already up to date.
        #[test]
        fn arbitrary_bytes_never_panic(
            bytes in proptest::collection::vec(any::<u8>(), 0..256),
            wrapped in any::<bool>(),
        ) {
            let content = if wrapped {
                [b"{\"mcpServers\": {".as_slice(), &bytes, b"}}"].concat()
            } else {
                bytes
            };
            let args = ["mcp".to_owned()];
            let _ = sermofur_mcp::mcp_config::has_entry(&content);
            let _ = without_entry(&content);
            if let Ok(Some(out)) = with_entry(Some(&content), "smf", &args) {
                prop_assert!(sermofur_mcp::mcp_config::has_entry(&out).unwrap_or(false));
                prop_assert_eq!(with_entry(Some(&out), "smf", &args).ok(), Some(None));
            }
        }

        #[test]
        fn install_then_remove_is_the_identity(
            names in proptest::collection::btree_set("[a-z\u{0}-\u{1F}\"\\\\\u{e9}\u{1F600} ]{1,9}", 0..5),
            spaced in any::<bool>(),
        ) {
            let servers: serde_json::Map<String, serde_json::Value> = names
                .into_iter()
                .filter(|n| n != "sermofur")
                .map(|n| (n.clone(), serde_json::json!({"command": n})))
                .collect();
            let document = serde_json::json!({"mcpServers": servers});
            let text = if spaced {
                serde_json::to_string_pretty(&document)
            } else {
                serde_json::to_string(&document)
            }
            .expect("JSON");
            let installed = with_entry(Some(text.as_bytes()), "smf", &["mcp".into(), "serve".into()])
                .expect("valid")
                .expect("changed");
            let removed = without_entry(&installed).expect("valid").expect("changed");
            prop_assert_eq!(removed, text.into_bytes());
        }
    }
}
